mapper.select:
SELECT E.JOB_EXECUTION_ID /* JOB실행ID */ , I.JOB_INSTANCE_ID /* JOB아이디(인스턴스ID) */ , I.JOB_NAME /* JOB명 */ , E.STATUS /* 상태 */ , E.CREATE_TIME /* 생성일시 */ , E.START_TIME /* 최종수행일시(시작시각) */ , E.END_TIME /* 종료일시 */ , E.EXIT_CODE /* 종료코드 */ , E.EXIT_MESSAGE /* 결과메세지 */ , E.LAST_UPDATED /* 최종수정일시 */ FROM BATCH_JOB_EXECUTION E INNER JOIN BATCH_JOB_INSTANCE I ON E.JOB_INSTANCE_ID = I.JOB_INSTANCE_ID
ORDER BY E.START_TIME DESC, E.JOB_EXECUTION_ID DESC
LIMIT #{INT_TO} OFFSET #{INT_FROM}
LIMIT #{INT_FROM}, #{INT_TO}
